"use strict";var protocols=require("protocols");function isSsh(r){if(Array.isArray(r))return-1!==r.indexOf("ssh")||-1!==r.indexOf("rsync");if("string"!=typeof r)return!1;var s=protocols(r);if(r=r.substring(r.indexOf("://")+3),isSsh(s))return!0;var e=new RegExp(".([a-zA-Z\\d]+):(\\d+)/");return!r.match(e)&&r.indexOf("@")<r.indexOf(":")}module.exports=isSsh;